/**
 * Printer AST — purpose-built, minimal, decoupled from TypeScript.
 *
 * The ref/filter/task deserializers return nodes in this AST; the printer
 * is the only module that turns them into TS source. Strings that would
 * otherwise get quote/escape foot-guns (e.g. `template` parts) live as
 * structured data until the final print step.
 *
 * Filter / sort / ref types live in `src/core/filters/ast.ts` and are
 * re-exported here for backwards compatibility. Other tool surfaces
 * (agent search tools, etc.) import the same definitions from there.
 */
import type { RefExpr, SortAst, ApprovalChainRefAst, DatamineRefAst, TableRefAst, AppRefAst, FieldRefAst, UserFieldRefAst, UnresolvedRefAst } from "../../shared/filters/ast.js";
import type { Filter } from "../../shared/filters/types.js";
import type { AutomationStatus } from "../build.js";
export type { RefExpr, SortAst, AppRefAst, ApprovalChainRefAst, DatamineRefAst, TableRefAst, FieldRefAst, UserFieldRefAst, UnresolvedRefAst, };
/**
 * A TaskCall represents one call to a task factory like `executeScript({...})`.
 * `args` is a map of argument-name -> value; the printer emits each value
 * according to its dynamic shape (RefExpr, Filter, nested object, etc.).
 *
 * `children` carries the AST for operator tasks (forEach / switch). For
 * forEach the array has exactly one entry; for switch each entry is a case
 * branch (plus optionally a default, marked with `isDefault`).
 */
export interface TaskCall {
    readonly factory: string;
    readonly refKey: string;
    readonly args: Record<string, unknown>;
    readonly children?: readonly OperatorChildAst[];
    /** The task's real wire display name, when it differs from `refKey` (e.g. a platform-authored "For Each" vs. the slugged `refKey` "For_Each"). */
    readonly displayName?: string;
    /** Explicit provider graph parent (`trigger` or another task refKey). */
    readonly hclParent?: string;
}
/** Opaque pulled calculation text with the scalar type validated by Ultron. */
export interface PulledRawCalculationAst {
    readonly kind: "calculationRaw";
    readonly text: string;
    readonly resultType: "attachment" | "bool" | "date" | "datetime" | "decimal" | "group" | "handle" | "html" | "json" | "multiPicklist" | "number" | "picklist" | "text" | "user";
}
export interface OperatorChildAst {
    readonly label?: string | null;
    /** True only for a switch default branch; label absence is not a default discriminator. */
    readonly isDefault?: boolean;
    readonly filter?: Filter<RefExpr, RefExpr>;
    readonly tasks: readonly TaskCall[];
    /** The switch default branch's actual display label when it deviates from "Default". */
    readonly defaultLabel?: string;
    /**
     * Which of the two mutually-exclusive wire shapes this switch default
     * branch was found in (`is_default = true` vs. an explicit
     * `filter = {type:"true"}`) — both are live-confirmed on real orgs for the
     * same case pattern (#157). Only set when the branch used the older
     * filter-based shape; unset means the newer `is_default` shape, which is
     * also to-tf.ts's default when this is absent (e.g. a freshly-authored
     * branch). Present so a rebuild reproduces the shape a pulled case
     * actually has instead of proposing a spurious "update".
     */
    readonly defaultFilterMode?: "isDefault" | "explicitTrueFilter";
}
export type TriggerAst = {
    kind: "onDemand";
    /** Schema entries, keyed by camelCase input name. */
    inputs: Array<{
        name: string;
        type: string;
        /** Required target for a record input; reconstructed from default_value. */
        app?: AppRefAst | UnresolvedRefAst;
        required?: boolean;
        multiple?: boolean;
        defaultValue?: unknown;
        description?: string;
    }>;
    /** Round-tripped from the wire's `onDemand.showTriggeredBy` flag. */
    showTriggeredBy?: boolean;
} | {
    kind: "recordCreate" | "recordUpdate" | "attachment";
    /** The owning app — `{kind: "unresolved", ...}` when the aspect never made it into the pull's catalog. */
    app: AppRefAst | UnresolvedRefAst;
    filter?: Filter<RefExpr, RefExpr>;
    changedFields?: readonly (FieldRefAst | UnresolvedRefAst)[];
    thinkUi?: boolean;
} | {
    kind: "commentAdded";
    app: AppRefAst | UnresolvedRefAst;
    conversationType: string;
    filter?: Filter<RefExpr, RefExpr>;
} | {
    kind: "conversationEnd";
    app: AppRefAst | UnresolvedRefAst;
    conversationType: string;
} | {
    kind: "webhook";
    authenticated: boolean;
    /** Raw passthrough — printer emits as-is. */
    customResponse?: {
        success?: {
            enabled: boolean;
            format: "JSON" | "XML" | "Text";
            statusCode?: number;
            body: string;
        };
        failure?: {
            enabled: boolean;
            format: "JSON" | "XML" | "Text";
            statusCode?: number;
            body: string;
        };
    };
} | {
    kind: "temporal";
    app: AppRefAst | UnresolvedRefAst;
    fieldKey: string;
    temporalUnit: "MINUTES" | "HOURS" | "DAYS";
    value: number;
} | {
    kind: "approvalProcessStatusUpdated";
    app: AppRefAst | UnresolvedRefAst;
    approvalChain?: string | ApprovalChainRefAst;
    status: "ACTIVE" | "STEP_APPROVED" | "CANCELLED" | "DENIED" | "APPROVED";
} | {
    kind: "schedule";
    frequency: "HOURLY" | "DAILY" | "WEEKLY" | "MONTHLY";
    interval?: number;
    timezone: string;
    startAt: string;
    weekdays?: readonly string[];
    dayOfMonth?: number;
} | {
    kind: "dataMine";
    datamine: DatamineRefAst | string;
    fireOnAlert?: boolean;
    fireOnRecovery?: boolean;
} | {
    kind: "emailReceived";
    emailAliasId: string;
} | {
    kind: "slackMessage";
} | {
    kind: "surveyResponseCreate";
    app: AppRefAst | UnresolvedRefAst;
    survey: string;
};
export interface AutomationAst {
    readonly ownerHandle: string;
    readonly name: string;
    readonly workflowRevision: string;
    readonly description?: string;
    readonly triggersOtherAutomations?: boolean;
    readonly status: AutomationStatus;
    readonly serviceAccountName?: string;
    readonly trigger: TriggerAst;
    readonly tasks: readonly TaskCall[];
    readonly outputs?: readonly {
        name: string;
        value: unknown;
    }[];
}
